  if (!quejaId) return []
  const { data, error } = await supabase
    .from('queja_adjuntos')
    .select('*')
    .eq('queja_id', quejaId)
    .order('created_at', { ascending: false })
  if (error) throw error
  return (data as QuejaAdjunto[]) ?? []
}

